	msPerRound?: number // computed from fireRate
	msPerRoundTouchScreen?: number // computed from fireRateWithHeldTouch

	altYVelocityInaccuracy?: number
	altInaccuracyFromJump?: number

	hasVerticalInaccuracy?: boolean

