export type InclusiveRange<N extends number, Arr extends number[] = []> = Arr["length"] extends N
	? Arr[number] | Arr["length"]
	: InclusiveRange<N, [...Arr, Arr["length"]]>

export type Bounds = Readonly<MutableBounds>

